function requestSeries(): void { clearHover(false); clips = clips.map((clip) => ({ ...clip, series: [] })); fullRange = undefined; viewRange = undefined; latestSeriesRequest = ++requestId; updateSelectionStatus(true); draw(); vscode.postMessage({ type: 'selectSignals', requestId: latestSeriesRequest, signalIds: [...selected] }); }
function updateSelectionStatus(loading = false): void { app.querySelector('.selection-status')!.textContent = loading ? t('Loading selected Signals…', '選択したSignalを読み込み中…') : `${selected.size} ${t('selected', '選択中')}`; }
