    const row = document.createElement('div'); row.className = 'legend-group'; row.style.top = `${top}px`;
    const title = document.createElement('span'); title.className = 'legend-title'; title.textContent = `${t('Graph', 'グラフ')} ${graphIndex + 1}`; const items = document.createElement('div'); items.className = 'legend-items';
    graph.forEach((group) => { for (const item of group.entries) {
      const entry = document.createElement('button'); entry.type = 'button'; entry.className = 'legend-entry'; entry.dataset.signalId = item.series.definition.id; entry.dataset.clipId = item.clip.id;
      entry.style.cssText = 'background:transparent;border:0;padding:2px 0;color:inherit;font:inherit;text-align:left';
      entry.addEventListener('mouseenter', () => highlightSignal(item.series.definition.id, item.clip.id)); entry.addEventListener('mouseleave', () => highlightSignal(entry.matches(':focus-visible') ? item.series.definition.id : undefined, item.clip.id));
      entry.addEventListener('focus', () => { if (entry.matches(':focus-visible')) highlightSignal(item.series.definition.id, item.clip.id); }); entry.addEventListener('blur', () => { if (!entry.matches(':hover')) highlightSignal(undefined); });
      const color = document.createElement('i'); color.style.borderTopColor = signalColor(item.series.definition.id); color.style.borderTopStyle = dashStyle(item.clipIndex); const label = document.createElement('span'); label.className = 'legend-label'; label.textContent = `${item.clip.name} · ${comparisonLegendLabel(item.series.definition, group.displayUnit)}`; entry.append(color, label); items.appendChild(entry);
    } }); row.append(title, items); host.appendChild(row); const height = Math.max(34, Math.ceil(row.scrollHeight) + 1); row.style.height = `${height}px`; heights.push(height); top += height + GRAPH_HEIGHT;
