function draw(renderControls = true): void {
  const entries = comparisonEntries(); const groups = comparisonGroups(entries); const graphs = comparisonGraphs(groups); const graphCount = Math.max(1, graphs.length); const nextFull = availableRange(entries); fullRange = nextFull; viewRange = reconcileViewRange(viewRange, nextFull); updateMeasuredSamples(graphs); updateZoomControls(); saveImageButton.disabled = !nextFull || !graphs.length || measured.pendingMarkers(); if (renderControls) renderLayoutEditor(); const wrap = canvas.parentElement!; const width = Math.max(320, wrap.clientWidth); if (renderControls || legendHeights.length !== graphCount) legendHeights = renderLegend(graphs, width); axisGutters = measureAxisGutters(graphs, width, true); let legendTop = 18; app.querySelectorAll<HTMLElement>('.legend-group').forEach((row, index) => { row.style.top = `${legendTop}px`; legendTop += (legendHeights[index] ?? 0) + GRAPH_HEIGHT + (axisGutters[index] ?? 0); }); const height = axisGutters.reduce((a, b) => a + b, 0) + 18 + graphCount * GRAPH_HEIGHT + legendHeights.reduce((sum, value) => sum + value, 0) + 34; const ratio = devicePixelRatio || 1; canvas.width = width * ratio; canvas.height = height * ratio; canvas.style.width = `${width}px`; canvas.style.height = `${height}px`; const context = canvas.getContext('2d')!; context.scale(ratio, ratio); context.clearRect(0, 0, width, height); context.fillStyle = css('--vscode-editor-background', '#1e1e1e'); context.fillRect(0, 0, width, height); hoverScale = undefined;
  if (!nextFull || !viewRange || !graphs.length) { context.fillStyle = css('--vscode-descriptionForeground', '#888'); context.fillText(selected.size ? t('No comparable samples for the selected Signals.', '選択したSignalに比較可能なサンプルがありません。') : t('Select Signals from the left pane.', '左側からSignalを選択してください。'), 20, 30); return; }
  hoverScale = { xMin: viewRange.start, xMax: viewRange.end, left: 92, width: Math.max(32, width - 184), graphCount: graphs.length }; paintChart(context, width, graphs, viewRange, legendHeights, 18, true);
}

function updateMeasuredSamples(graphs: readonly ComparisonGraph[]): void {
  const queries: MeasuredSampleQuery[] = []; const graphIds = comparisonGraphSignalIds(graphs);
  const addQueries = (slot: string, graph: ComparisonGraph | undefined, relativeTimestamp: number) => {
    const byClip = new Map<string, { clip: ComparisonClipDto; ids: Set<string> }>();
    for (const group of graph ?? []) for (const entry of group.entries) {
      const value = byClip.get(entry.clip.id) ?? { clip: entry.clip, ids: new Set<string>() }; value.ids.add(entry.series.definition.id); byClip.set(entry.clip.id, value);
    }
    for (const [id, value] of byClip) queries.push({ slot: `${slot}:${id}`, sourceId: id, timestamp: value.clip.anchorTimestamp + relativeTimestamp, signalIds: [...value.ids] });
  };
  if (viewRange) {
    for (const marker of markers.values()) {
      const index = findGraphIndexBySignals(graphIds, marker.signalIds);
      if (index !== undefined && marker.relativeTimestamp >= viewRange.start && marker.relativeTimestamp <= viewRange.end) addQueries(`marker:${marker.id}`, graphs[index], marker.relativeTimestamp);
    }
  }
  measured.update(queries);
}

function graphReferenceTimestamp(slot: string, reference: number, graph: ComparisonGraph): number | undefined {
  const entries = graph.flatMap((group) => group.entries);
  if (entries.some((entry) => !measured.ready(`${slot}:${entry.clip.id}`))) return undefined;
  return nearestMeasuredTimestamp(reference, entries.flatMap((entry) => {
    const sample = measured.sample(`${slot}:${entry.clip.id}`, entry.series.definition.id);
    return sample ? [sample.timestamp - entry.clip.anchorTimestamp] : [];
  }));
}

