          const separated = !connectGaps && previousTimestamp !== undefined && crossesSeriesGap(entry.series.gaps, previousTimestamp, sample.timestamp); const px = x(sample.timestamp - entry.clip.anchorTimestamp); const py = y(value);
          started && !separated ? context.lineTo(px, py) : context.moveTo(px, py); started = true; previousTimestamp = sample.timestamp;
