function hover(event: MouseEvent): void { const position = positionAt(event); if (!position) { clearHover(); return; } hoverRelativeTimestamp = position.relativeTimestamp; hoverGraphIndex = position.graphIndex; scheduleInteractionDraw(); }
function addMarker(event: MouseEvent): void { const position = positionAt(event); if (!position) return; const signalIds = comparisonGraphSignalIds(comparisonGraphs(comparisonGroups(comparisonEntries())))[position.graphIndex]; if (!signalIds?.length) return; const id = `marker-${++markerCounter}`; markers.set(id, { id, relativeTimestamp: position.relativeTimestamp, signalIds }); clearHover(false); updateMarkerControls(); draw(false); }
function positionAt(event: MouseEvent): { readonly relativeTimestamp: number; readonly graphIndex: number } | undefined { if (!hoverScale || !selected.size || !visibleClips.size) return undefined; const rect = canvas.getBoundingClientRect(); const position = event.clientX - rect.left; const graphY = event.clientY - rect.top - 18; const graphIndex = graphIndexAtOffset(graphY, legendHeights, axisGutters); if (position < hoverScale.left || position > hoverScale.left + hoverScale.width || graphIndex === undefined || graphIndex >= hoverScale.graphCount) return undefined; const fraction = (position - hoverScale.left) / hoverScale.width; return { relativeTimestamp: hoverScale.xMin + fraction * (hoverScale.xMax - hoverScale.xMin), graphIndex }; }

function zoom(factor: number, center?: number): void { if (!fullRange || !viewRange) return; const fullSpan = fullRange.end - fullRange.start || 1; const currentSpan = viewRange.end - viewRange.start || fullSpan; const span = Math.max(fullSpan * .005, Math.min(fullSpan, currentSpan * factor)); const pivot = center ?? (viewRange.start + viewRange.end) / 2; const ratio = (pivot - viewRange.start) / currentSpan; let start = pivot - span * ratio; let end = start + span; if (start < fullRange.start) { start = fullRange.start; end = start + span; } if (end > fullRange.end) { end = fullRange.end; start = end - span; } viewRange = { start, end }; clearHover(false); draw(false); }
function pan(direction: -1 | 1): void { if (!fullRange || !viewRange) return; const fullSpan = fullRange.end - fullRange.start; const span = viewRange.end - viewRange.start; if (span >= fullSpan - 1e-12) return; const shift = span * .18 * direction; let start = viewRange.start + shift; let end = viewRange.end + shift; if (start < fullRange.start) { start = fullRange.start; end = start + span; } if (end > fullRange.end) { end = fullRange.end; start = end - span; } viewRange = { start, end }; clearHover(false); draw(false); }
function handleWheel(event: WheelEvent): void { if (!fullRange || !viewRange) return; const gesture = chartWheelGesture(event, canvas.clientWidth); if (gesture.kind === 'scroll' || !gesture.delta) return; event.preventDefault(); if (viewportTimer !== undefined) window.clearTimeout(viewportTimer); const center = gesture.kind === 'zoom' ? positionAt(event as unknown as MouseEvent)?.relativeTimestamp : undefined; viewportTimer = window.setTimeout(() => { viewportTimer = undefined; if (gesture.kind === 'zoom') zoom(gesture.delta < 0 ? 1 / 1.5 : 1.5, center); else pan(Math.sign(gesture.delta) < 0 ? -1 : 1); }, 70); }
function updateZoomControls(): void { const zoomed = Boolean(fullRange && viewRange && (Math.abs(viewRange.start - fullRange.start) > 1e-9 || Math.abs(viewRange.end - fullRange.end) > 1e-9)); app.querySelector<HTMLButtonElement>('.zoom-reset')!.disabled = !zoomed; app.querySelector<HTMLButtonElement>('.zoom-out')!.disabled = !zoomed; app.querySelector<HTMLButtonElement>('.zoom-in')!.disabled = !fullRange || !viewRange || (viewRange.end - viewRange.start) <= (fullRange.end - fullRange.start) * .005 + 1e-12; app.querySelector<HTMLButtonElement>('.pan-left')!.disabled = !zoomed || !fullRange || !viewRange || viewRange.start <= fullRange.start + 1e-12; app.querySelector<HTMLButtonElement>('.pan-right')!.disabled = !zoomed || !fullRange || !viewRange || viewRange.end >= fullRange.end - 1e-12; app.querySelector('.view-range')!.textContent = viewRange ? `${format(viewRange.start)}–${format(viewRange.end)} s · ${format(viewRange.end - viewRange.start)} s` : ''; }

function saveImage(): void { const graphs = comparisonGraphs(comparisonGroups(comparisonEntries())); if (!viewRange || !graphs.length || saveImageButton.disabled) return; const width = 1600; const exportCanvas = document.createElement('canvas'); exportCanvas.width = width; let context = exportCanvas.getContext('2d'); if (!context) return; const heights = graphs.map((graph) => measureGraphLegendHeight(context!, graph, width)); const gutters = measureAxisGutters(graphs, width, false); const contentHeight = gutters.reduce((a, b) => a + b, 0) + graphs.length * GRAPH_HEIGHT + heights.reduce((sum, value) => sum + value, 0); const height = Math.max(900, 92 + contentHeight); exportCanvas.height = height; context = exportCanvas.getContext('2d'); if (!context) return; const label = `${format(viewRange.start)}–${format(viewRange.end)} s`; paintComparisonExport(context, width, height, graphs, heights, gutters, label); const vector = createSvgCanvas(width, height); paintComparisonExport(vector.context, width, height, graphs, heights, gutters, label); vscode.postMessage({ type: 'saveClipComparisonImage', pngDataUrl: exportCanvas.toDataURL('image/png'), svg: vector.toSvg() }); }
function paintComparisonExport(context: CanvasRenderingContext2D, width: number, height: number, graphs: readonly ComparisonGraph[], heights: readonly number[], gutters: readonly number[], label: string): void { context.fillStyle = css('--vscode-editor-background', '#1e1e1e'); context.fillRect(0, 0, width, height); context.fillStyle = css('--vscode-foreground', '#ddd'); context.font = '600 22px sans-serif'; context.fillText('SigMixa · Clip Comparison', 24, 34); context.font = '12px sans-serif'; context.fillStyle = css('--vscode-descriptionForeground', '#999'); context.fillText(label, width - context.measureText(label).width - 24, 32); paintChart(context, width, graphs, viewRange!, heights, 58, false, gutters); }
function paintGraphLegend(context: CanvasRenderingContext2D, graph: ComparisonGraph, graphIndex: number, width: number, top: number): void { context.save(); context.font = '600 12px sans-serif'; context.fillStyle = css('--vscode-descriptionForeground', '#999'); context.fillText(`${t('Graph', 'グラフ')} ${graphIndex + 1}`, 24, top + 20); let x = 94; let y = top + 20; context.font = '12px sans-serif'; graph.forEach((group) => { for (const item of group.entries) { const label = `${item.clip.name} · ${comparisonLegendLabel(item.series.definition, group.displayUnit)}`; const entryWidth = 30 + context.measureText(label).width; if (x + entryWidth > width - 24) { x = 94; y += 20; } context.setLineDash(dashPatterns[item.clipIndex % dashPatterns.length]); context.strokeStyle = signalColor(item.series.definition.id); context.lineWidth = 3; context.beginPath(); context.moveTo(x, y - 4); context.lineTo(x + 16, y - 4); context.stroke(); context.setLineDash([]); context.fillStyle = css('--vscode-foreground', '#ddd'); context.fillText(ellipsize(context, label, width - x - 28), x + 22, y); x += Math.min(entryWidth, width - x - 24) + 16; } }); context.restore(); }
function measureGraphLegendHeight(context: CanvasRenderingContext2D, graph: ComparisonGraph, width: number): number { context.save(); context.font = '12px sans-serif'; let x = 94; let rows = 1; graph.forEach((group) => { for (const item of group.entries) { const label = `${item.clip.name} · ${comparisonLegendLabel(item.series.definition, group.displayUnit)}`; const entryWidth = 30 + context.measureText(label).width; if (x + entryWidth > width - 24) { x = 94; rows++; } x += Math.min(entryWidth, width - x - 24) + 16; } }); context.restore(); return Math.max(34, 12 + rows * 20); }

function clearHover(redraw = true): void { hoverRelativeTimestamp = undefined; hoverGraphIndex = undefined; if (redraw) scheduleInteractionDraw(); }
function scheduleInteractionDraw(): void { if (interactionDrawScheduled) return; interactionDrawScheduled = true; requestAnimationFrame(() => { interactionDrawScheduled = false; draw(false); }); }
function paintHoverValues(context: CanvasRenderingContext2D, cursorX: number, values: readonly CanvasHoverValue[], left: number, right: number, top: number, bottom: number, occupied: HoverLabelRect[] = []): void { context.save(); context.font = `600 11px ${css('--vscode-editor-font-family', 'monospace')}`; context.textBaseline = 'middle'; const positioned = layoutHoverLabelBoxes(values.map((value) => ({ ...value, cursorX, width: context.measureText(value.text).width + 10, height: 16 })), { left, right, top, bottom }, occupied); for (const value of positioned) { context.setLineDash(value.lineDash); context.strokeStyle = value.color; context.globalAlpha = .7; context.beginPath(); if (value.sampleX >= left && value.sampleX <= right && value.sampleY >= top && value.sampleY <= bottom) { context.arc(value.sampleX, value.sampleY, 3, 0, Math.PI * 2); context.fillStyle = value.color; context.fill(); context.moveTo(value.sampleX, value.sampleY); context.lineTo(value.placeLeft ? value.boxX + value.width : value.boxX, value.labelY); context.stroke(); } context.globalAlpha = .92; context.fillStyle = css('--vscode-editorHoverWidget-background', '#252526'); context.fillRect(value.boxX, value.boxY, value.width, value.height); context.globalAlpha = 1; context.strokeStyle = value.color; context.strokeRect(value.boxX, value.boxY, value.width, value.height); context.fillStyle = value.color; context.fillText(value.text, value.boxX + 5, value.labelY); } context.setLineDash([]); occupied.push(...positioned.map((value) => value.rect)); context.restore(); }
function createTimestampMarker(context: CanvasRenderingContext2D, cursorX: number, text: string, left: number, right: number, bottom: number, occupied: readonly HoverLabelRect[] = [], top = 0): CanvasTimestampMarker { context.save(); context.font = `600 11px ${css('--vscode-editor-font-family', 'monospace')}`; const width = context.measureText(text).width + 12; context.restore(); return { text, cursorX, bottom, rect: layoutTimestampMarker(cursorX, width, 18, left, right, bottom, occupied, top) }; }
function paintTimestampMarker(context: CanvasRenderingContext2D, marker: CanvasTimestampMarker): void { context.save(); context.font = `600 11px ${css('--vscode-editor-font-family', 'monospace')}`; context.textAlign = 'center'; context.textBaseline = 'middle'; context.fillStyle = css('--vscode-editorHoverWidget-background', '#252526'); context.fillRect(marker.rect.x, marker.rect.y, marker.rect.width, marker.rect.height); context.strokeStyle = css('--vscode-editorCursor-foreground', '#fff'); context.strokeRect(marker.rect.x, marker.rect.y, marker.rect.width, marker.rect.height); context.fillStyle = css('--vscode-editor-foreground', '#ddd'); context.fillText(marker.text, marker.rect.x + marker.rect.width / 2, marker.rect.y + marker.rect.height / 2); context.restore(); }
function updateMarkerControls(): void { markerClear.disabled = markers.size === 0; }

function availableRange(entries: readonly ComparisonEntry[]): TimeRange | undefined { let start = Infinity; let end = -Infinity; for (const entry of entries) for (const sample of entry.series.samples) { if (!Number.isFinite(sample.value)) continue; const relative = sample.timestamp - entry.clip.anchorTimestamp; start = Math.min(start, relative); end = Math.max(end, relative); } if (!Number.isFinite(start) || !Number.isFinite(end)) return undefined; return { start, end: end === start ? start + 1 : end }; }
function reconcileViewRange(view: TimeRange | undefined, full: TimeRange | undefined): TimeRange | undefined { if (!full || !view) return full; const fullSpan = full.end - full.start; const span = Math.min(fullSpan, Math.max(0, view.end - view.start)); if (span >= fullSpan || view.end < full.start || view.start > full.end) return full; const start = Math.max(full.start, Math.min(view.start, full.end - span)); return { start, end: start + span }; }
function comparisonGroupRange(group: ComparisonGroup, visible: TimeRange): { minimum: number; maximum: number } { if (normalized) return { minimum: 0, maximum: 100 }; if (axisRange.mode === 'global') return displaySeriesRange(group.entries.map((entry) => entry.series), axisRange, undefined, group.displayUnit); let minimum = Infinity; let maximum = -Infinity; for (const entry of group.entries) for (const sample of entry.series.samples) { const relative = sample.timestamp - entry.clip.anchorTimestamp; if (relative < visible.start || relative > visible.end || (sample.quality !== undefined && sample.quality !== 'valid')) continue; const value = comparisonValue(entry.series, sample.value, group.displayUnit); if (!Number.isFinite(value)) continue; minimum = Math.min(minimum, value); maximum = Math.max(maximum, value); } if (!Number.isFinite(minimum) || !Number.isFinite(maximum)) return displaySeriesRange(group.entries.map((entry) => entry.series), axisRange, undefined, group.displayUnit); if (axisRange.includeZero) { minimum = Math.min(0, minimum); maximum = Math.max(0, maximum); } return { minimum, maximum }; }
function comparisonEntries(): readonly ComparisonEntry[] { const active = clips.filter((clip) => visibleClips.has(clip.id)); return active.flatMap((clip) => clip.series.map((series) => ({ clip, clipIndex: clips.findIndex((item) => item.id === clip.id), series }))); }
function comparisonGroups(entries: readonly ComparisonEntry[]): readonly ComparisonGroup[] { return normalized ? entries.length ? [{ key: 'normalized', label: '0–100%', entries }] : [] : groupComparisonSeries(entries); }
function comparisonGraphSignalIds(graphs: readonly ComparisonGraph[]): readonly string[][] { return graphs.map((graph) => [...new Set(graph.flatMap((group) => group.entries.map((entry) => entry.series.definition.id)))]); }
function graphIndexAtOffset(offset: number, heights: readonly number[], gutters: readonly number[] = []): number | undefined { if (offset < 0) return undefined; let top = 0; for (let index = 0; index < heights.length; index++) { const legendBottom = top + heights[index]; if (offset < legendBottom) return undefined; const graphBottom = legendBottom + GRAPH_HEIGHT; if (offset < graphBottom) return index; if (offset < graphBottom + (gutters[index] ?? 0)) return undefined; top = graphBottom + (gutters[index] ?? 0); } return undefined; }
function groupComparisonSeries(entries: readonly ComparisonEntry[]): readonly ComparisonGroup[] { const groups = new Map<string, { key: string; order: number; entries: ComparisonEntry[] }>(); for (const entry of entries) { const unit = entry.series.definition.unit?.trim(); const conversion = resolveDisplayUnit(unit); const key = conversion ? `family:${conversion.family}` : unit ? `unit:${unit.toLowerCase()}` : 'empty'; const group = groups.get(key) ?? { key, order: conversion?.order ?? (unit ? 10_000 : 20_000), entries: [] }; group.entries.push(entry); groups.set(key, group); } return [...groups.values()].map((group) => { const displayUnit = preferredDisplayUnit(group.entries.map((entry) => entry.series.definition.unit)); return { ...group, displayUnit, label: displayUnit ?? t('(no unit)', '(単位なし)') }; }).sort((left, right) => left.order - right.order || left.label.localeCompare(right.label)); }
function comparisonValue(series: ComparisonEntry['series'], value: number, displayUnit?: string): number { return normalized ? normalizeValue(value, series.globalMinimum ?? value, series.globalMaximum ?? value) : convertDisplayUnit(value, series.definition.unit, displayUnit); }
function displayValueLabel(value: number, displayUnit?: string): string { const unit = normalized ? '%' : displayUnit?.trim(); return `${format(value)}${unit ? ` ${unit}` : ''}`; }
function comparisonLegendLabel(definition: ComparisonEntry['series']['definition'], displayUnit?: string): string { const sourceUnit = definition.unit?.trim(); const unit = !normalized && displayUnit && sourceUnit && displayUnit !== sourceUnit ? `${sourceUnit} → ${displayUnit}` : sourceUnit; return `${definition.name}${unit ? ` (${unit})` : ''}`; }
function css(name: string, fallback: string): string { return getComputedStyle(document.documentElement).getPropertyValue(name).trim() || fallback; }
function format(value: number): string { return Number(value.toPrecision(7)).toString(); }
function ellipsize(context: CanvasRenderingContext2D, text: string, maxWidth: number): string { if (context.measureText(text).width <= maxWidth) return text; let low = 0; let high = text.length; while (low < high) { const middle = Math.ceil((low + high) / 2); if (context.measureText(`${text.slice(0, middle)}…`).width <= maxWidth) low = middle; else high = middle - 1; } return `${text.slice(0, low)}…`; }

window.addEventListener('message', (event: MessageEvent<ClipComparisonToWebview>) => { const message = event.data; if (message.type === 'measuredSignals') { measured.receive(message.requestId, message.samples); } else if (message.type === 'init') { measured.invalidate(); clips = message.clips.map((clip) => ({ ...clip })); visibleClips.clear(); clips.forEach((clip) => visibleClips.add(clip.id)); selected.clear(); message.selectedSignalIds.forEach((id) => selected.add(id)); colors.clear(); message.definitions.forEach((definition, index) => colors.set(definition.id, SIGNAL_COLOR_PRESETS[index % SIGNAL_COLOR_PRESETS.length])); selector.setCatalog(message.definitions, message.groups); updateSelectionStatus(); renderClips(); updateModeButtons(); draw(); } else if (message.type === 'seriesChanged' && message.requestId === latestSeriesRequest) { measured.invalidate(); const next = new Map(message.seriesByClip.map((item) => [item.clipId, item.series])); clips = clips.map((clip) => ({ ...clip, series: next.get(clip.id) ?? [] })); updateSelectionStatus(); draw(); } else if (message.type === 'anchorChanged') { updateLocalAnchor(message.clipId, message.anchorTimestamp); clearHover(false); scheduleInteractionDraw(); } });

vscode.postMessage({ type: 'ready' });
